// Dashboard logic. All numbers come from window.DATA (site/data.js), generated by `python -m src.main build`.
const D = window.DATA || {stats: {total_apps: 0, researched: 0, pending: 0, manually_verified: 0}, apps: [], catalogue: [], accuracy: {status: "Manual verification pending."}};
const S = D.stats;
const $ = (id) => document.getElementById(id);
const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({"&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;"}[c]));
const pct = (n, d) => (d ? Math.round((100 * n) / d) : 0);
const pillClass = (v) => String(v).split(" ")[0];
const pill = (v) => `<span class="pill ${pillClass(v)}">${esc(v || "Unknown")}</span>`;
const byId = Object.fromEntries(D.apps.map((a) => [a.app_id, a]));
const MIN_FOR_PATTERNS = 10;

// ---- A. Overview ----
$("overview-cards").innerHTML = [
  ["Total apps", S.total_apps, "catalogue"],
  ["Researched", S.researched, "completed"],
  ["Pending", S.pending, "remaining"],
  ["Verified", D.apps.filter((a) => a.evidence === "Verified").length, "evidence confirmed"],
  ["Manually reviewed", S.manually_verified, "human-checked"],
].map(([l, v, meta]) => `<div class="metric-card"><div class="metric-label">${l}</div><div class="metric-value">${v}</div><div class="metric-meta">${meta}</div></div>`).join("");
const completion = pct(S.researched, S.total_apps);
$("progress-card").innerHTML = `<div class="progress-copy"><div><span class="status-dot"></span><b>Research progress</b></div><strong>${completion}%</strong></div>
  <div class="progress-track" role="progressbar" aria-label="Research completion" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${completion}"><i style="width:${completion}%"></i></div>
  <div class="progress-meta"><span>${S.researched} of ${S.total_apps} apps researched</span><span>${S.pending} pending</span></div>`;
if (S.researched === 0) {
  document.querySelector(".hero-heading").insertAdjacentHTML("afterend",
    `<div class="banner"><b>Research is ready to begin.</b> Run <code>python -m src.main pilot</code>, then <code>python -m src.main build</code> to populate this dashboard from saved data.</div>`);
}

// ---- B. Summary ----
function bars(title, obj) {
  const entries = Object.entries(obj || {}).sort((a, b) => b[1] - a[1]);
  const max = Math.max(1, ...entries.map((e) => e[1]));
  const body = entries.length
    ? entries.map(([k, v]) => `<div class="bar"><span>${esc(k)}</span><div class="t"><i style="width:${pct(v, max)}%"></i></div><em>${v}</em></div>`).join("")
    : `<p class="empty">No data yet.</p>`;
  return `<div class="panel"><h3>${title}</h3>${body}</div>`;
}
$("summary-grid").innerHTML = [
  bars("Authentication methods", S.auth), bars("Developer access", S.access),
  bars("API types", S.api_types), bars("MCP availability", S.mcp),
  bars("Buildability", S.buildability), bars("Main blockers", S.blockers),
  bars("Evidence status", S.evidence),
  `<div class="panel"><h3>Verified-only sample</h3><p class="verified-sample"><b>${S.verified?.n || 0}</b> verified of ${S.researched} researched apps</p>
    <p class="muted">Pending and Unverified records are excluded from this view.</p></div>`,
].join("");

// ---- C. Catalogue ----
const rows = D.catalogue.map((c) => ({c, r: byId[c.id]}));
function fillSelect(id, label, values) {
  $(id).innerHTML = `<option value="">${label}</option>` + [...new Set(values)].sort().map((v) => `<option>${esc(v)}</option>`).join("");
}
fillSelect("f-cat", "All categories", D.catalogue.map((c) => c.category));
fillSelect("f-build", "Any buildability", D.apps.map((a) => a.buildability));
fillSelect("f-mcp", "Any MCP status", D.apps.map((a) => a.mcp));
fillSelect("f-ev", "Any evidence", D.apps.map((a) => a.evidence));

function renderTable() {
  const q = $("q").value.trim().toLowerCase(), cat = $("f-cat").value, b = $("f-build").value, m = $("f-mcp").value, e = $("f-ev").value;
  const shown = rows.filter(({c, r}) => {
    const searchable = [c.name, c.category, r?.description, r?.auth_methods?.join(" "), r?.api_types?.join(" "), r?.mcp, r?.evidence].join(" ").toLowerCase();
    return (!q || searchable.includes(q)) && (!cat || c.category === cat) &&
      (!b || r?.buildability === b) && (!m || r?.mcp === m) && (!e || r?.evidence === e);
  });
  $("count").textContent = `${shown.length} of ${rows.length} applications`;
  $("tbl").tBodies[0].innerHTML = shown.map(({c, r}) => r
    ? `<tr data-id="${c.id}" tabindex="0" aria-label="Open ${esc(c.name)} details"><td><div class="app-name"><span class="app-avatar">${esc(c.name.slice(0,1).toUpperCase())}</span><b>${esc(c.name)}</b></div></td><td>${esc(c.category)}</td><td>${esc(r.auth_methods.join(", "))}</td><td>${esc(r.access)}</td><td>${esc(r.api_types.join(", "))}</td><td>${pill(r.mcp)}</td><td>${pill(r.buildability)}</td><td>${pill(r.evidence)}</td></tr>`
    : `<tr data-id="${c.id}" tabindex="0" aria-label="Open ${esc(c.name)} details"><td><div class="app-name"><span class="app-avatar">${esc(c.name.slice(0,1).toUpperCase())}</span><b>${esc(c.name)}</b></div></td><td>${esc(c.category)}</td><td colspan="6"><span class="pending-status"><i></i>Pending research</span></td></tr>`).join("");
  if (!shown.length) {
    $("tbl").tBodies[0].innerHTML = `<tr><td colspan="8"><div class="table-empty"><b>No matching applications</b><span>Try clearing a filter or changing your search.</span></div></td></tr>`;
  }
}
["q", "f-cat", "f-build", "f-mcp", "f-ev"].forEach((id) => $(id).addEventListener("input", renderTable));
["f-cat", "f-build", "f-mcp", "f-ev"].forEach((id) => $(id).addEventListener("change", renderTable));
$("clear-filters").addEventListener("click", () => {
  ["q", "f-cat", "f-build", "f-mcp", "f-ev"].forEach((id) => $(id).value = "");
  renderTable();
});
renderTable();

function openDetails(tr) {
  if (!tr?.dataset.id) return;
  const id = +tr.dataset.id, c = D.catalogue.find((x) => x.id === id), r = byId[id];
  const evidenceLinks = (urls) => urls?.length
    ? `<div class="source-links">${urls.map((u) => `<a href="${esc(u)}" target="_blank" rel="noopener"><span>↗</span>${esc(u)}</a>`).join("")}</div>`
    : `<span class="no-source">No evidence link</span>`;
  const sources = r?.sources?.length ? r.sources : [];
  $("detail").innerHTML = `<div class="dialog-top"><div class="app-name"><span class="app-avatar">${esc(c.name.slice(0,1).toUpperCase())}</span><div><h3 id="detail-title">${esc(c.name)}</h3><p class="muted">${esc(c.category)}</p></div></div><button class="close" type="button" aria-label="Close details">×</button></div>` +
    (r ? `<div class="detail-status">${pill(r.evidence)} ${pill(r.buildability)}</div>
      <dl class="detail-grid">
        <div><dt>What it does</dt><dd>${esc(r.description)}</dd></div>
        <div><dt>Authentication</dt><dd>${esc(r.auth_methods.join(", "))}</dd></div>
        <div><dt>Developer access</dt><dd>${esc(r.access)}</dd></div>
        <div><dt>API availability</dt><dd>${esc(r.api_types.join(", "))}</dd></div>
        <div><dt>API coverage</dt><dd>${esc(r.api_breadth)}</dd></div>
        <div><dt>MCP availability</dt><dd>${esc(r.mcp)}${r.mcp_url ? ` · <a href="${esc(r.mcp_url)}" target="_blank" rel="noopener">Official link ↗</a>` : ""}</dd></div>
        <div><dt>Blocker</dt><dd>${esc(r.blocker_type)}${r.blocker && r.blocker !== "None found" ? `: ${esc(r.blocker)}` : ""}</dd></div>
        <div><dt>Researched</dt><dd>${esc(r.researched_at)}</dd></div>
      </dl>
      <div class="evidence-section"><h4>Evidence sources</h4>
        <div class="source-group"><span>Authentication</span>${evidenceLinks(r.auth_sources)}</div>
        <div class="source-group"><span>API availability</span>${evidenceLinks(r.api_sources)}</div>
        <div class="source-group"><span>MCP availability</span>${evidenceLinks(r.mcp_sources)}</div>
        ${sources.length ? `<div class="source-group"><span>Additional sources</span>${evidenceLinks(sources)}</div>` : ""}
      </div>
      ${r.notes ? `<div class="detail-note"><b>Research notes</b><span>${esc(r.notes)}</span></div>` : ""}`
      : `<div class="table-empty"><b>This app has not been researched</b><span>Run the pilot or selected research command, then rebuild the dashboard.</span></div>`);
  $("detail").querySelector(".close").addEventListener("click", () => $("detail").close());
  $("detail").showModal();
}
$("tbl").tBodies[0].addEventListener("click", (ev) => openDetails(ev.target.closest("tr")));
$("tbl").tBodies[0].addEventListener("keydown", (ev) => {
  if (ev.key === "Enter" || ev.key === " ") { ev.preventDefault(); openDetails(ev.target.closest("tr")); }
});

// ---- D. Patterns (written only from data; hidden until enough apps are done) ----
function topEntry(obj, skip = []) { return Object.entries(obj || {}).filter(([k]) => !skip.includes(k)).sort((a, b) => b[1] - a[1])[0]; }
function patterns() {
  const n = S.researched;
  const verified = S.verified || {n: 0};
  if (n === 0) {
    return `<div class="banner"><b>Insights are not available yet.</b> No app research has been saved. Run a pilot or selected research pass, then rebuild the dashboard.</div>`;
  }
  const complete = verified.n > 0;
  const out = [];
  const a = topEntry(complete ? verified.auth : S.auth, ["Unknown"]);
  if (a) out.push(`Among ${complete ? "verified" : "researched"} apps, <b>${esc(a[0])}</b> appears most often (${a[1]} app${a[1] === 1 ? "" : "s"} in a sample of ${complete ? verified.n : n}).`);
  const api = topEntry(complete ? verified.api_types : S.api_types, ["Unknown"]);
  if (api) out.push(`The most frequently identified API type is <b>${esc(api[0])}</b>, reported in ${api[1]} app${api[1] === 1 ? "" : "s"}.`);
  const mcp = topEntry(complete ? verified.mcp : S.mcp, ["Unknown"]);
  if (mcp) out.push(`MCP status <b>${esc(mcp[0])}</b> is the most common in the available sample.`);
  const build = topEntry(complete ? verified.buildability : S.buildability, ["Unknown"]);
  if (build) out.push(`The most common buildability verdict is <b>${esc(build[0])}</b> (${build[1]} app${build[1] === 1 ? "" : "s"}).`);
  const blocker = topEntry(complete ? verified.blockers : S.blockers, ["Unknown"]);
  if (blocker) out.push(`The most common reported integration blocker is <b>${esc(blocker[0])}</b> (${blocker[1]} app${blocker[1] === 1 ? "" : "s"}).`);
  else out.push(`No integration blocker is common enough to summarize from the current verified data.`);

  const categoryRows = Object.entries(S.verified_by_category || {}).map(([name, v]) =>
    `<tr><td><b>${esc(name)}</b></td><td>${v.n}</td><td>${esc(Object.entries(v.access).sort((x,y)=>y[1]-x[1])[0]?.[0] || "Unknown")}</td><td>${esc(Object.entries(v.mcp).sort((x,y)=>y[1]-x[1])[0]?.[0] || "Unknown")}</td></tr>`
  ).join("");
  const categoryTable = categoryRows
    ? `<div class="table-wrap"><table><thead><tr><th>Category</th><th>Verified sample</th><th>Most common access</th><th>Most common MCP status</th></tr></thead><tbody>${categoryRows}</tbody></table></div>`
    : `<p class="empty">No verified category findings are available yet.</p>`;
  const list = (arr) => (arr.length ? arr.map(esc).join(", ") : "None identified in the current data");
  return `${verified.n === 0 ? `<div class="banner">No Verified records are available. This view uses researched records, but these findings are incomplete until Verified evidence is present.</div>` : ""}
    <div class="insight-list">${out.map((x) => `<div class="insight-item"><span>•</span><p>${x}</p></div>`).join("")}</div>
    <div class="two"><div class="panel"><h3>Easy wins</h3><p>${list(S.easy_wins)}</p></div>
    <div class="panel"><h3>Potential outreach or difficult integrations</h3><p>${list(S.needs_outreach)}</p></div></div>
    <div class="panel category-findings"><h3>Category findings</h3>${categoryTable}</div>
    <p class="muted">Based on ${n} researched apps${complete ? ` and ${verified.n} Verified apps` : ""}. No result is implied for apps that are pending or lack evidence.</p>`;
}
$("patterns-body").innerHTML = patterns();

// ---- E. Verification ----
function verification() {
  const acc = D.accuracy;
  if (!acc || acc.status !== "ok") {
    const pending = acc?.fields_pending || 0;
    return `<div class="verification-summary"><div><span>Fields reviewed</span><strong>0</strong></div><div><span>Awaiting review</span><strong>${pending}</strong></div></div>
      <div class="banner">No fields have been manually checked yet.</div>
      <p class="muted">Run <code>python -m src.main review-sample</code>, open each official documentation link, fill <code>human_result</code>, <code>verdict</code>, <code>source_url</code> and <code>notes</code> in <code>data/human_reviews.csv</code>, then run <code>python -m src.main build</code>. Accuracy will use only rows with a recorded verdict.</p>`;
  }
  const passes = Object.entries(acc.by_pass);
  const t = passes.map(([p, v]) => `<tr><td>Pass ${esc(p)}</td><td>${v.apps_checked}</td><td>${v.fields_checked}</td><td>${v.correct} / ${v.partial} / ${v.incorrect}</td><td><b>${v.strict_accuracy}%</b></td><td>${v.lenient_accuracy}%</td></tr>`).join("");
  const fields = Object.entries(passes.at(-1)[1].by_field).map(([f, v]) => `<div class="bar"><span>${esc(f)}</span><div class="t"><i style="width:${v.strict}%"></i></div><em>${v.strict}%</em></div>`).join("");
  const reviewedRows = (acc.rows || []).map((r) =>
    `<tr><td><b>${esc(r.app_name)}</b></td><td>${esc(r.field)}</td><td>${esc(r.automated_result)}</td><td>${esc(r.human_result)}</td><td>${pill(r.verdict)}</td><td>${r.source_url ? `<a href="${esc(r.source_url)}" target="_blank" rel="noopener">Official evidence ↗</a>` : "No URL"}</td><td>${esc(r.notes || "—")}</td></tr>`
  ).join("");
  return `<div class="verification-summary"><div><span>Fields reviewed</span><strong>${acc.fields_reviewed}</strong></div><div><span>Awaiting review</span><strong>${acc.fields_pending}</strong></div></div>
    <div class="table-wrap"><table><thead><tr><th>Round</th><th>Apps</th><th>Fields checked</th><th>Correct / partial / wrong</th><th>Strict accuracy</th><th>Lenient</th></tr></thead><tbody>${t}</tbody></table></div>
    <p class="muted">Strict counts only "Correct". Lenient counts "Partially correct" as half. Only fields a human actually checked are included.</p>
    <div class="panel"><h3>Accuracy by field (latest round)</h3>${fields}</div>
    <div class="panel verification-records"><h3>Reviewer comparison</h3><div class="table-wrap"><table><thead><tr><th>App</th><th>Field</th><th>Automated</th><th>Human verified</th><th>Verdict</th><th>Evidence</th><th>Notes</th></tr></thead><tbody>${reviewedRows}</tbody></table></div></div>`;
}
$("verification-body").innerHTML = verification();

$("refresh-info").addEventListener("click", () => {
  $("detail").innerHTML = `<div class="dialog-top"><div><h3 id="detail-title">Refresh research data</h3><p class="muted">Run commands from the project directory.</p></div><button class="close" type="button" aria-label="Close">×</button></div>
    <div class="detail-note"><b>Pilot</b><span><code>python -m src.main pilot</code></span></div>
    <div class="detail-note"><b>Selected apps</b><span><code>python -m src.main research --ids 5 12 71</code></span></div>
    <div class="detail-note"><b>All apps</b><span><code>python -m src.main research --all</code></span></div>
    <div class="detail-note"><b>Refresh dashboard</b><span><code>python -m src.main build</code></span></div>`;
  $("detail").querySelector(".close").addEventListener("click", () => $("detail").close());
  $("detail").showModal();
});
